def normalize_language(value: object, *, default: str = DEFAULT_LANGUAGE) -> str:
    """Normalize a UI language code without ever raising during GUI startup."""
    candidate = str(value or "").strip().lower().replace("_", "-")
    aliases = {
        "no": "nb",
        "nb-no": "nb",
        "no-no": "nb",
        "en-us": "en",
        "en-gb": "en",
    }
    candidate = aliases.get(candidate, candidate)
    if candidate in _TRANSLATIONS:
        return candidate
    if default in _TRANSLATIONS:
        return default
    return FALLBACK_LANGUAGE


def translate(key: str, language: str = DEFAULT_LANGUAGE, **values: object) -> str:
    """Translate a user-facing key with English fallback.

    Missing English keys are returned in a controlled technical form instead of
    raising an exception in the GUI.
    """
    normalized = normalize_language(language, default=FALLBACK_LANGUAGE)
    text = _TRANSLATIONS.get(normalized, {}).get(key)
    if text is None:
        text = _TRANSLATIONS.get(FALLBACK_LANGUAGE, {}).get(key)
    if text is None:
        return f"[missing: {key}]"
    try:
        return text.format(**values)
    except (KeyError, ValueError, IndexError):
        # A translator typo must not prevent the GUI from opening.  Returning a
        # controlled marker also makes the defect visible in tests and review.
        return f"[format-error: {key}]"


def catalog_keys(language: str) -> frozenset[str]:
    """Return translation keys present in one maintained catalog."""
    normalized = normalize_language(language, default=FALLBACK_LANGUAGE)
    return frozenset(_TRANSLATIONS.get(normalized, {}))


def missing_catalog_keys(language: str, reference: str = FALLBACK_LANGUAGE) -> tuple[str, ...]:
    """Return keys missing from *language* compared with *reference*."""
    target = catalog_keys(language)
    required = catalog_keys(reference)
    return tuple(sorted(required - target))
